using UnityEngine;using LWS.TruckSports;
namespace LWS.TruckSkeeBall {
public enum SkeePhase{Ready,Approach,Flight,Landing,Result,Replay,Waiting}
public sealed class SkeeRunner:MonoBehaviour {
 public SkeeMatch match;public int lane,owner;public SportsEventTruck truck;public Transform target,cabAnchor;public SportsEventCamera viewCamera;public SportsCabLook look;public SportsMotionReplay replay;public SkeeRing[] rings;public ParticleSystem celebration;public SkeePhase Phase{get;private set;}public int Delivery{get;private set;}public int Award{get;private set;}public int RingPasses{get;private set;}public Vector3 LaunchVelocity{get;private set;}public Vector3 LaunchPosition{get;private set;}public readonly SportsLimitedAftertouch touch=new SportsLimitedAftertouch();
 Vector3 previous;Quaternion previousRotation;float age,quiet,timer,flightAge;int entering=-1;bool replayNeutral;float navWait;
 public float Center=>lane*38;public float Age=>age;public float FlightAge=>flightAge;public bool Done=>Phase==SkeePhase.Waiting;public bool ReplayLive=>Phase==SkeePhase.Replay;
 public void ResetCourse(int participant){owner=participant;truck.slot=owner;if(viewCamera.cabSteering!=null)viewCamera.cabSteering.Bind(truck);replay.End();replay.Colorize(new[]{match.setup.players[owner].color});Phase=SkeePhase.Waiting;RingPasses=0;celebration.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);foreach(var ring in rings)ring.ResetLight();StartAttempt();}
 public bool StartAttempt(){if(!match.rules.CanLaunch(owner)){Phase=SkeePhase.Waiting;return false;}Delivery=match.rules.attempts[owner]+1;Award=0;age=quiet=flightAge=0;timer=1.2f;entering=-1;replayNeutral=false;navWait=0;truck.Prepare(new Vector3(Center,.7f,2),Quaternion.identity);truck.maxSpeed=34;truck.motorTorque=16;truck.Power(false);truck.body.isKinematic=true;Phase=SkeePhase.Ready;previous=truck.body.position;previousRotation=truck.body.rotation;touch.Reset(1.25f,Vector2.up);replay.ResetRecord();look.ResetLook();match.Plan(this);return true;}
 Vector3 Local(Vector3 point)=>target.InverseTransformPoint(point);
 void PlaneBounds(Vector3 position,Quaternion rotation,out float min,out float max){min=float.MaxValue;max=float.MinValue;var half=Vector3.Scale(truck.shape.size*.5f,truck.transform.lossyScale);var center=truck.shape.center;for(int i=0;i<8;i++){var point=Local(position+rotation*(center+Vector3.Scale(half,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1))));min=Mathf.Min(min,point.z);max=Mathf.Max(max,point.z);}}
 bool Inside(int ring,Vector3 position,Quaternion rotation){var half=Vector3.Scale(truck.shape.size*.5f,truck.transform.lossyScale);var center=truck.shape.center;for(int i=0;i<8;i++){var p=Local(position+rotation*(center+Vector3.Scale(half,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1))));if((new Vector2(p.x,p.y)-rings[ring].center).sqrMagnitude>Mathf.Pow(rings[ring].radius-.015f,2))return false;}return true;}
 // Observe the completed physics step, including the whole rear chassis. No trigger callback decides points.
 public void Observe(){if(Phase==SkeePhase.Flight||Phase==SkeePhase.Landing){PlaneBounds(previous,previousRotation,out var beforeMin,out var beforeMax);PlaneBounds(truck.body.position,truck.body.rotation,out var nowMin,out var nowMax);if(beforeMax<0&&nowMax>=0){float t=Mathf.InverseLerp(beforeMax,nowMax,0);var p=Vector3.Lerp(previous,truck.body.position,t);var q=Quaternion.Slerp(previousRotation,truck.body.rotation,t);entering=-1;for(int i=0;i<rings.Length;i++)if(Inside(i,p,q)){entering=i;break;}}if(entering>=0&&beforeMin<0&&nowMin>=0){float t=Mathf.InverseLerp(beforeMin,nowMin,0);var p=Vector3.Lerp(previous,truck.body.position,t);var q=Quaternion.Slerp(previousRotation,truck.body.rotation,t);if(Inside(entering,p,q)){RingPasses++;Resolve(rings[entering].points,"OPENING CLEARED");rings[entering].Celebrate();}else entering=-1;}if(nowMax<-.1f)entering=-1;}previous=truck.body.position;previousRotation=truck.body.rotation;}
 public void Tick(Vector2 input,bool action,float dt){age+=dt;if(Phase==SkeePhase.Ready){timer-=dt;if(timer<=0){truck.body.isKinematic=false;truck.Power(true);Phase=SkeePhase.Approach;}return;}if(Phase==SkeePhase.Approach){truck.TickDrive(input);if(truck.body.position.z>=43.8f&&!truck.Grounded&&truck.body.linearVelocity.z>2){Phase=SkeePhase.Flight;LaunchVelocity=truck.body.linearVelocity;LaunchPosition=truck.body.worldCenterOfMass;flightAge=0;touch.Reset(1.25f,input);truck.Power(false);match.Launched(this);}else if(age>32||truck.body.position.y< -3||Mathf.Abs(truck.body.position.x-Center)>15)Resolve(0,"MISSED APPROACH");}
 else if(Phase==SkeePhase.Flight){flightAge+=dt;touch.Tick(truck.body,input,dt,.8f);if(truck.body.position.y< -2||truck.body.position.z>108||Mathf.Abs(truck.body.position.x-Center)>17||flightAge>18)Resolve(0,"MISS");}
 else if(Phase==SkeePhase.Landing){flightAge+=dt;bool slow=truck.body.linearVelocity.sqrMagnitude<.09f&&truck.body.angularVelocity.sqrMagnitude<.16f;quiet=slow?quiet+dt:0;if(quiet>=1.1f||truck.body.position.y< -2||flightAge>22)Resolve(0,"OUTSIDE OPENING");}
 else if(Phase==SkeePhase.Result){timer-=dt;if(timer<=0){replay.Record(age+.051f,1);truck.Power(false);truck.body.isKinematic=true;truck.gameObject.SetActive(false);replay.Begin(Mathf.Max(0,age-6));Phase=SkeePhase.Replay;timer=0;}}
 else if(Phase==SkeePhase.Replay){timer+=dt;if(!replayNeutral){if(input.sqrMagnitude<.04f&&!action)replayNeutral=true;}else{navWait=Mathf.Max(0,navWait-dt);if(navWait<=0&&Mathf.Abs(input.x)>.65f){replay.Angle=(replay.Angle+(input.x>0?1:2))%3;navWait=.3f;}if(navWait<=0&&Mathf.Abs(input.y)>.65f){replay.Speed=input.y>0?2:.5f;navWait=.3f;}}bool over=replay.Step(dt);if(over||replayNeutral&&action||match.IsAI(owner)&&timer>1.2f||timer>10){replay.End();truck.gameObject.SetActive(true);truck.body.isKinematic=true;Phase=SkeePhase.Waiting;match.AttemptViewed(this);}return;}
 if(Phase==SkeePhase.Approach||Phase==SkeePhase.Flight||Phase==SkeePhase.Landing||Phase==SkeePhase.Result)replay.Record(age,1);}
 public void Resolve(int points,string reason){if(Phase!=SkeePhase.Approach&&Phase!=SkeePhase.Flight&&Phase!=SkeePhase.Landing)return;if(!match.rules.Lock(owner,Delivery,points))return;Award=points;Phase=SkeePhase.Result;truck.Power(false);timer=points>=50?1.8f:.9f;match.Resolved(this,reason);if(points>0){celebration.transform.position=truck.body.position;celebration.Play();}}
 public void ContactBoard(){if(Phase==SkeePhase.Flight){Phase=SkeePhase.Landing;truck.Power(false);}}
 void OnCollisionEnter(Collision contact){if(!match.Live)return;if(contact.collider.GetComponentInParent<SkeeBoard>()!=null)ContactBoard();if(Phase==SkeePhase.Approach||Phase==SkeePhase.Flight||Phase==SkeePhase.Landing){match.feedback.Play(1,contact.relativeVelocity.magnitude);if(contact.collider.name=="Course miss floor")Resolve(0,"GROUND MISS");}}
 public void Freeze(){truck.Power(false);truck.body.isKinematic=true;replay.End();look.ReleaseCursor();}void OnDisable(){if(look!=null)look.ReleaseCursor();}
}
}
